import AppKit
import SwiftUI

/// The ScamShield brand mark: a clean shield outline. Changing the path here rebrands everywhere
/// (menu bar template image, scanner, app icon generated by the snapshot tool).
public struct ShieldShape: Shape {
    public init() {}

    /// Visual centre of the outline as fractions of its rect: the area centroid of this path
    /// (computed from the curves below). The shield tapers to a point, so its centroid sits
    /// slightly above the rect's middle. Inner marks are centred here, not on the frame.
    public static let visualCenter = CGPoint(x: 0.5, y: 0.488)

    public func path(in rect: CGRect) -> Path {
        let w = rect.width, h = rect.height
        let x = rect.minX, y = rect.minY
        var p = Path()
        p.move(to: CGPoint(x: x + w * 0.5, y: y))
        p.addCurve(to: CGPoint(x: x + w, y: y + h * 0.17),
                   control1: CGPoint(x: x + w * 0.68, y: y + h * 0.11),
                   control2: CGPoint(x: x + w * 0.86, y: y + h * 0.16))
        p.addLine(to: CGPoint(x: x + w, y: y + h * 0.47))
        p.addCurve(to: CGPoint(x: x + w * 0.5, y: y + h),
                   control1: CGPoint(x: x + w, y: y + h * 0.75),
                   control2: CGPoint(x: x + w * 0.78, y: y + h * 0.9))
        p.addCurve(to: CGPoint(x: x, y: y + h * 0.47),
                   control1: CGPoint(x: x + w * 0.22, y: y + h * 0.9),
                   control2: CGPoint(x: x, y: y + h * 0.75))
        p.addLine(to: CGPoint(x: x, y: y + h * 0.17))
        p.addCurve(to: CGPoint(x: x + w * 0.5, y: y),
                   control1: CGPoint(x: x + w * 0.14, y: y + h * 0.16),
                   control2: CGPoint(x: x + w * 0.32, y: y + h * 0.11))
        p.closeSubpath()
        return p
    }
}

/// The check-stroke inside the shield, in the SAME rect as `ShieldShape`, with its bounding box
/// centred on `ShieldShape.visualCenter`. (Previously the tick was laid out in the square of the
/// height while the shield is only 0.82 × as wide, which pushed it ~12 % of the width right.)
public struct ShieldCheckShape: Shape {
    public init() {}

    /// Tick vertices as fractions of the shield rect (width = 0.82 × height). Spans 0.287…0.713
    /// horizontally and 0.363…0.613 vertically → bounding-box centre (0.5, 0.488).
    static let points: [CGPoint] = [
        CGPoint(x: 0.287, y: 0.483),
        CGPoint(x: 0.445, y: 0.613),
        CGPoint(x: 0.713, y: 0.363),
    ]

    public func path(in rect: CGRect) -> Path {
        var p = Path()
        p.addLines(Self.points.map { CGPoint(x: rect.minX + rect.width * $0.x, y: rect.minY + rect.height * $0.y) })
        return p
    }
}

/// Shield with an inner check-stroke, used as the in-app mark.
public struct ShieldMark: View {
    var lineWidth: CGFloat
    public init(lineWidth: CGFloat = 3) { self.lineWidth = lineWidth }

    /// Width / height of the shield outline.
    public static let aspectRatio: CGFloat = 0.82

    public var body: some View {
        GeometryReader { geo in
            let s = min(geo.size.width, geo.size.height)
            ZStack {
                ShieldShape().stroke(style: StrokeStyle(lineWidth: lineWidth, lineJoin: .round))
                ShieldCheckShape().stroke(style: StrokeStyle(lineWidth: lineWidth, lineCap: .round, lineJoin: .round))
            }
            .frame(width: s * Self.aspectRatio, height: s)
            .frame(width: geo.size.width, height: geo.size.height)
        }
    }
}

public enum MenuBarIcon {
    /// Template image (adapts to light/dark menu bar and highlight) drawn from `ShieldShape`.
    @MainActor
    public static func image(pointSize: CGFloat = 18) -> NSImage {
        let size = NSSize(width: pointSize, height: pointSize)
        let image = NSImage(size: size, flipped: true) { rect in
            guard let ctx = NSGraphicsContext.current?.cgContext else { return false }
            let inset = rect.insetBy(dx: rect.width * 0.17, dy: rect.height * 0.08)
            let shield = ShieldShape().path(in: inset).cgPath
            ctx.addPath(shield)
            ctx.setLineWidth(1.6)
            ctx.setLineJoin(.round)
            ctx.setStrokeColor(NSColor.black.cgColor)
            ctx.strokePath()
            // small inner dot = "scanner lens", centred on the shield's visual centre
            let r = rect.width * 0.11
            let c = CGPoint(x: inset.minX + inset.width * ShieldShape.visualCenter.x,
                            y: inset.minY + inset.height * ShieldShape.visualCenter.y)
            ctx.setFillColor(NSColor.black.cgColor)
            ctx.fillEllipse(in: CGRect(x: c.x - r, y: c.y - r, width: r * 2, height: r * 2))
            return true
        }
        image.isTemplate = true
        image.accessibilityDescription = "ScamShield"
        return image
    }
}
